<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {api,date,type Staff,type Page} from '../api'
import {pending,busy} from '../commands'
import {uuidPattern} from '../customerCommands'
import {readTicketPolicy,readDiscoverySources,enrollDiscovery,stopDiscovery,retryDiscovery,discoveryPending,type DiscoveryPolicy,type DiscoverySource} from '../stockReturnDiscovery'
import {readReturnJob,type ReturnJob} from '../stockReturnRecovery'
import {readReturnReceipt,type StockReturn} from '../stockReturns'
const props=defineProps<{staff:Staff;ticketId:string;disabled:boolean}>()
const policy=ref<DiscoveryPolicy|null>(null),sources=ref<Page<DiscoverySource>|null>(null),enabled=ref(false),loading=ref(false),error=ref(''),maxSources=ref(10),page=ref(1),confirmStop=ref(false),work=ref<{source:DiscoverySource;job:ReturnJob;receipt:StockReturn}|null>(null)
let generation=0,disposed=false
const owns=computed(()=>discoveryPending()&&pending.value?.owner===props.staff.username)
const blocked=computed(()=>props.disabled||loading.value||busy.value||!!pending.value||!!error.value||!props.staff.canWrite)
const state=(s:string)=>({ACTIVE:'尋找未來來源',EXHAUSTED:'來源額度已用完',STOPPED:'已永久停止',WAITING:'等待背景核對',LEASED:'背景核對中',DONE:'工作已完成',REVIEW:'待人工核對',REGISTERED:'返還已登記',CLOSED:'投影保持封鎖',APPLIED:'原返還已完成',BLOCKED:'原返還受阻'}[s]||s)
async function load(){const g=++generation,id=props.ticketId;policy.value=null;sources.value=null;work.value=null;confirmStop.value=false;loading.value=true;error.value='';try{const settings=await api<{enabled:boolean}>('/admin/stock/return-discovery/settings');if(typeof settings?.enabled!=='boolean')throw new Error('授權設定回覆不完整');const p=uuidPattern.test(id)?await readTicketPolicy(id):null;const rows=p?await readDiscoverySources(p,page.value):null;if(disposed||g!==generation)return;enabled.value=settings.enabled;policy.value=p;sources.value=rows}catch(e){if(!disposed&&g===generation)error.value=(e as Error).message}finally{if(g===generation)loading.value=false}}
async function operate(kind:'enroll'|'stop'|'recover'){if(kind!=='recover'&&blocked.value)return;error.value='';try{if(kind==='enroll')await enrollDiscovery(props.staff,props.ticketId,maxSources.value);else if(kind==='stop'&&policy.value)await stopDiscovery(props.staff,policy.value);else if(kind==='recover'&&owns.value)await retryDiscovery(props.staff);await load()}catch(e){error.value=(e as Error).message}}
async function readWork(source:DiscoverySource){if(!policy.value||!source.returnRequestId||busy.value||loading.value)return;const g=generation,p=policy.value;loading.value=true;error.value='';work.value=null;try{const job=await readReturnJob(props.staff,source.returnRequestId,source.releaseRevision);if(!job)throw new Error('原背景工作尚未查證');const receipt=await readReturnReceipt(props.staff,source.returnRequestId,p.ticketId,source.orderId,source.releaseRevision);if(job.state==='DONE'&&receipt.state!=='APPLIED')throw new Error('工作完成與返還證據不一致，請重讀核對');if(!disposed&&g===generation)work.value={source,job,receipt}}catch(e){if(!disposed&&g===generation)error.value=(e as Error).message}finally{if(g===generation)loading.value=false}}
watch(()=>props.ticketId,()=>{page.value=1;load()},{immediate:true});watch(()=>pending.value,()=>{confirmStop.value=false})
onBeforeUnmount(()=>{disposed=true;generation++})
</script>
<style scoped>
code { overflow-wrap: anywhere; }
</style>
<template><section id="return-discovery" class="panel" aria-label="自動返還授權"><h2>自動返還授權</h2><p>只處理授權後、證據完整的新取消或到期來源。每票種一份有限授權，不能重設額度或重新啟用。</p><p v-if="error" class="notice error" role="alert">{{error}}</p><div v-if="discoveryPending()" class="notice warning"><p>原授權或停止命令尚未確認，其他寫入暫停。原員工：{{pending?.owner}}</p><code>{{pending?.body.requestId}}</code><button v-if="owns" :disabled="busy||loading" @click="operate('recover')">核對原自動返還操作</button><p v-else>請由原員工登入核對，不接管原內容。</p></div><p v-if="!uuidPattern.test(ticketId)" class="muted">先從票種投影清單選擇票種。</p><template v-else><button :disabled="loading||busy" @click="load">重讀自動返還授權</button><p v-if="!enabled" class="notice">自動返還目前關閉；既有授權與原命令仍可核對或永久停止。</p><form v-if="!policy&&staff.canWrite" @submit.prevent="operate('enroll')"><label>最多處理來源數<input v-model.number="maxSources" type="number" min="1" max="100" step="1" required :disabled="blocked||!enabled" /></label><p>保存時固定目前來源邊界，不回填歷史。登記與 WAITING 都不代表已返還。</p><button class="primary" :disabled="blocked||!enabled">授權未來返還來源</button></form><p v-else-if="!policy&&!loading">尚無可讀的本人授權；唯讀員工不能建立或停止授權。</p><div v-if="policy" data-discovery-policy><p role="status">{{state(policy.state)}} · 已用 {{policy.discovered}}／{{policy.maxSources}} 個來源 · 版本 {{policy.version}}</p><p>原授權 <code>{{policy.requestId}}</code> · 僅接受修訂 {{policy.startRevision}} 之後的來源</p><p v-if="policy.state==='EXHAUSTED'">不再發現新來源；已登記工作仍可完成。</p><p v-if="policy.state==='STOPPED'">永久停止自動續做；不撤回已完成返還，也不能取消已送出的命令。</p><button v-if="staff.canWrite&&policy.state!=='STOPPED'" :disabled="blocked" @click="confirmStop=true">永久停止自動返還授權</button><div v-if="confirmStop" class="notice warning"><p>確認後不可重新啟用。已送出的命令與原工作仍需核對；不重開嘗試預算。</p><button :disabled="blocked" @click="operate('stop')">確認永久停止自動返還</button><button :disabled="busy" @click="confirmStop=false">返回</button></div><h3>已發現來源</h3><p v-if="!sources?.items.length">尚未發現新來源；不會掃回歷史來源。</p><article v-for="s in sources?.items" :key="s.orderId" class="stock-issue" :data-discovery-source="s.orderId"><p>訂單 <code>{{s.orderId}}</code> · 修訂 {{s.releaseRevision}} · {{date(s.createdAt)}}</p><p v-if="s.disposition==='EXISTING_RETURN'">已有返還操作，僅保留來源紀錄，不接管其他工作。</p><template v-else><p>已登記原返還 <code>{{s.returnRequestId}}</code>，需核對完成證據。</p><button :disabled="busy||loading" @click="readWork(s)">核對原返還工作</button></template></article><div v-if="sources" class="pagination"><button :disabled="page===1||loading||busy" @click="page--;load()">上一頁來源</button><span>{{page}} · {{sources.total}} 個來源</span><button :disabled="page*sources.size>=sources.total||loading||busy" @click="page++;load()">下一頁來源</button></div><section v-if="work" aria-label="自動返還原工作"><h3>原返還與背景工作</h3><p>原編號 <code>{{work.receipt.requestId}}</code></p><p>{{state(work.job.state)}} · 已用 {{work.job.attempts}}／{{work.job.maxAttempts}} 次 · {{work.job.lastCode||'待領取'}}</p><p role="status">{{state(work.receipt.state)}} · {{work.receipt.failure||'已保存'}} · 目前世代 {{work.receipt.currentGeneration}}</p><p v-if="work.receipt.state!=='APPLIED'">尚未確認返還完成；背景登記或來源額度耗盡不代表完成。</p><p v-if="work.job.state==='REVIEW'">請由原管理員在原返還流程人工核對，保留原編號與預算。</p></section></div></template></section></template>
